package output

import (
	"bytes"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
)

// MarkerFile marks a directory as generated by dbfolio.
// Only directories containing a valid marker are cleaned before regeneration.
const MarkerFile = ".dbfolio"

// markerSignature is the first line of the marker. Checking the content (not just the
// name) prevents a ".dbfolio" created by someone else from authorizing deletion.
const markerSignature = "This directory is generated by dbfolio."

const markerContent = markerSignature + " Its contents are replaced on every build.\n"

// ErrNotEmpty is returned when the output directory has files that dbfolio did not generate.
var ErrNotEmpty = errors.New("output directory is not empty and was not generated by dbfolio (use --force to write into it)")

// Prepare makes dir ready for writing generated files.
//
//   - missing or empty: created as needed and marked as dbfolio output
//   - contains a valid MarkerFile: previous output is removed so that pages of dropped tables do not linger
//   - other non-empty directory: ErrNotEmpty, unless force is set; with force, existing files are
//     left in place (only overwritten) and the marker is NOT written, so the directory never
//     becomes eligible for cleaning on a later build
func Prepare(dir string, force bool) error {
	info, err := os.Stat(dir)
	switch {
	case errors.Is(err, os.ErrNotExist):
		if err := os.MkdirAll(dir, 0o755); err != nil {
			return fmt.Errorf("create output directory: %w", err)
		}
	case err != nil:
		return fmt.Errorf("check output directory: %w", err)
	case !info.IsDir():
		return fmt.Errorf("output path %s is not a directory", dir)
	default:
		owned, err := cleanExisting(dir, force)
		if err != nil {
			return err
		}
		if !owned {
			return nil
		}
	}

	if err := os.WriteFile(filepath.Join(dir, MarkerFile), []byte(markerContent), 0o644); err != nil {
		return fmt.Errorf("write marker file: %w", err)
	}
	return nil
}

// cleanExisting reports whether dir is owned by dbfolio (empty or validly marked),
// removing previous output when it is.
func cleanExisting(dir string, force bool) (owned bool, err error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return false, fmt.Errorf("read output directory: %w", err)
	}
	if len(entries) == 0 {
		return true, nil
	}

	marked, err := hasValidMarker(dir)
	if err != nil {
		return false, err
	}
	if !marked {
		if force {
			return false, nil
		}
		return false, fmt.Errorf("%s: %w", dir, ErrNotEmpty)
	}

	if err := guardCleaning(dir); err != nil {
		return false, err
	}
	// RemoveAll deletes symlinks themselves and never follows them, so link targets are safe.
	// The marker goes last so that an interrupted clean can be retried without --force.
	for _, e := range entries {
		if e.Name() == MarkerFile {
			continue
		}
		if err := os.RemoveAll(filepath.Join(dir, e.Name())); err != nil {
			return false, fmt.Errorf("clean output directory: %w", err)
		}
	}
	if err := os.Remove(filepath.Join(dir, MarkerFile)); err != nil {
		return false, fmt.Errorf("clean output directory: %w", err)
	}
	return true, nil
}

func hasValidMarker(dir string) (bool, error) {
	path := filepath.Join(dir, MarkerFile)
	// Lstat: a symlink or directory named .dbfolio is not our marker.
	info, err := os.Lstat(path)
	if errors.Is(err, os.ErrNotExist) {
		return false, nil
	}
	if err != nil {
		return false, fmt.Errorf("check marker file: %w", err)
	}
	if !info.Mode().IsRegular() {
		return false, nil
	}
	f, err := os.Open(path)
	if err != nil {
		return false, fmt.Errorf("read marker file: %w", err)
	}
	defer func() { _ = f.Close() }() // read-only; a close error cannot affect the result
	head := make([]byte, len(markerSignature))
	if _, err := io.ReadFull(f, head); err != nil {
		// Shorter than the signature: not our marker.
		return false, nil
	}
	return bytes.Equal(head, []byte(markerSignature)), nil
}

// guardCleaning is a last line of defense against wiping important directories,
// e.g. if a marker was copied there by mistake.
func guardCleaning(dir string) error {
	// Resolve symlinks so that a link pointing at a protected directory is caught too.
	abs, err := filepath.Abs(dir)
	if err == nil {
		abs, err = filepath.EvalSymlinks(abs)
	}
	if err != nil {
		return fmt.Errorf("resolve output directory: %w", err)
	}
	if abs == filepath.Dir(abs) {
		return fmt.Errorf("refusing to clean filesystem root %s", abs)
	}
	// SameFile also handles case-insensitive file systems and symlinked home directories.
	if home, err := os.UserHomeDir(); err == nil && sameDir(abs, home) {
		return fmt.Errorf("refusing to clean home directory %s", abs)
	}
	if _, err := os.Lstat(filepath.Join(abs, ".git")); err == nil {
		return fmt.Errorf("refusing to clean %s: it contains .git", abs)
	}
	return nil
}

func sameDir(a, b string) bool {
	ai, err := os.Stat(a)
	if err != nil {
		return false
	}
	bi, err := os.Stat(b)
	if err != nil {
		return false
	}
	return os.SameFile(ai, bi)
}

// CreateDir creates a subdirectory for generated content. An existing symlink
// (or other non-directory) is rejected so that files are never written outside
// the output directory through it.
func CreateDir(path string) error {
	info, err := os.Lstat(path)
	switch {
	case errors.Is(err, os.ErrNotExist):
		if err := os.Mkdir(path, 0o755); err != nil {
			return fmt.Errorf("create %s: %w", path, err)
		}
		return nil
	case err != nil:
		return fmt.Errorf("check %s: %w", path, err)
	case !info.IsDir():
		return fmt.Errorf("%s exists and is not a directory", path)
	default:
		return nil
	}
}

// CreateFile creates path for writing generated content. An existing entry is removed
// first so that a symlink planted in the output directory is replaced, not followed.
func CreateFile(path string) (*os.File, error) {
	if err := os.Remove(path); err != nil && !errors.Is(err, os.ErrNotExist) {
		return nil, fmt.Errorf("replace %s: %w", path, err)
	}
	f, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o644)
	if err != nil {
		return nil, fmt.Errorf("create %s: %w", path, err)
	}
	return f, nil
}
